def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    n = len(sites)
    p = s.get('element_properties') or {}
    radii = [(p.get(a.get('element')) or {}).get('covalent_radius_A') for a in sites]
    occ = [max(a.get('occupancy', 1.0) or 0.0, 0.0) for a in sites]
    population = {}
    for i in range(n):
        if radii[i] is not None and radii[i] > 0:
            e = sites[i].get('element')
            population[e] = population.get(e, 0.0) + occ[i]
    count = sum(population.values())
    if count <= 0:
        return 0.0
    baseline = sum(x * x for x in population.values()) / (count * count)
    same = 0.0
    weight = 0.0
    for b in s.get('neighbors') or []:
        i = b.get('i', -1)
        j = b.get('j', -1)
        d = b.get('distance_A') or 0.0
        if 0 <= i < n and 0 <= j < n and d > 1e-8:
            ri = radii[i]
            rj = radii[j]
            if ri is not None and rj is not None and ri > 0 and rj > 0:
                q = d / (ri + rj)
                if q < 3.0:
                    w = occ[i] * occ[j] * exp(-((q / 1.25) ** 6))
                    weight += w
                    if sites[i].get('element') == sites[j].get('element'):
                        same += w
    return same / weight - baseline if weight > 1e-12 else 0.0

def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    n = len(sites)
    p = s.get('element_properties') or {}
    props = [p.get(a.get('element')) or {} for a in sites]
    radii = [a.get('covalent_radius_A') for a in props]
    occ = [max(a.get('occupancy', 1.0) or 0.0, 0.0) for a in sites]
    chi = []
    gap = []
    for a in props:
        ie = a.get('first_ionization_energy_eV')
        ea = a.get('electron_affinity_eV')
        if ie is not None and ea is not None and ie - ea > 1e-8:
            chi.append(0.5 * (ie + ea))
            gap.append(ie - ea)
        else:
            chi.append(None)
            gap.append(None)
    weight = sum(occ[i] for i in range(n) if chi[i] is not None and radii[i] is not None and radii[i] > 0)
    if weight <= 0:
        return 0.0
    total = 0.0
    for b in s.get('neighbors') or []:
        i = b.get('i', -1)
        j = b.get('j', -1)
        d = b.get('distance_A') or 0.0
        if 0 <= i < n and 0 <= j < n and d > 1e-8:
            ri = radii[i]
            rj = radii[j]
            if ri is not None and rj is not None and ri > 0 and rj > 0 and chi[i] is not None and chi[j] is not None:
                q = d / (ri + rj)
                if q < 3.0:
                    w = occ[i] * occ[j] * exp(-((q / 1.25) ** 6))
                    total += w * (chi[i] - chi[j]) ** 2 / (gap[i] + gap[j])
    return total / (2.0 * weight)

def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    n = len(sites)
    elements = {a.get('element'): 1 for a in sites if (a.get('occupancy', 1.0) or 0.0) > 0}
    if len(elements) <= 1:
        return 0.0
    p = s.get('element_properties') or {}
    radii = [(p.get(a.get('element')) or {}).get('covalent_radius_A') for a in sites]
    occ = [max(a.get('occupancy', 1.0) or 0.0, 0.0) for a in sites]
    nearest = [inf for a in sites]
    unlike = [inf for a in sites]
    for b in s.get('neighbors') or []:
        i = b.get('i', -1)
        j = b.get('j', -1)
        d = b.get('distance_A') or 0.0
        if 0 <= i < n and 0 <= j < n and d > 1e-8 and occ[j] > 0:
            ri = radii[i]
            rj = radii[j]
            if ri is not None and rj is not None and ri > 0 and rj > 0:
                q = d / (ri + rj)
                nearest[i] = min(nearest[i], q)
                if sites[i].get('element') != sites[j].get('element'):
                    unlike[i] = min(unlike[i], q)
    total = 0.0
    weight = 0.0
    for i in range(n):
        if nearest[i] < inf and occ[i] > 0:
            gap = min(max(unlike[i] - nearest[i], 0.0), 3.0) if unlike[i] < inf else 3.0
            total += occ[i] * gap
            weight += occ[i]
    return total / weight if weight > 0 else 0.0
